const sd = $getWorkflowStaticData('global');
const c = $input.first().json;
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Africa/Cairo' });
if (!c.forceRun && sd.uploadingDay === today) {
  // An upload was already started today (maybe failed). Never auto-retry: avoids duplicate videos.
  return [];
}
sd.attempts = 0;
sd.feedback = '';
sd.polls = 0;
return $input.all();

const sd = $getWorkflowStaticData('global');
const c = $('Config').first().json;
sd.attempts = (sd.attempts || 0) + 1;
if (sd.attempts > 3) throw new Error('Quality gate failed 3 times. Last problem: ' + (sd.feedback || 'unknown'));
const chars = JSON.parse(c.charactersJson);
const themes = String(c.themes).split('|').map((s) => s.trim()).filter(Boolean);
if (!sd.theme || sd.attempts === 1) sd.theme = themes[Math.floor(Math.random() * themes.length)];
const past = (sd.titles || []).slice(-40);
const cast = chars.map((x) => '- ' + x.name + ': ' + x.trait).join('\n');
const prompt = `You are the head writer of "BOMBO || بومبو", a hit Arabic YouTube Shorts cartoon channel about talking cats. Channel promise: friendship, laughter, adventures.
Write ONE brand-new, self-contained episode that runs 60-90 seconds when spoken. All spoken lines are in Egyptian Arabic dialect (عامية مصرية), written in Arabic script.

CAST (use only these exact names as speakers):
${cast}

TODAY'S THEME: ${sd.theme}
Do NOT repeat or resemble these past episodes: ${JSON.stringify(past)}
${sd.feedback || ''}

RULES
- The very first line must hook the viewer within 3 seconds: a shout, a funny problem, or a surprising situation.
- Structure: hook, problem, 2-3 escalating funny attempts, a twist, a warm friendly ending. Do NOT write a subscribe call-to-action; it is added automatically.
- Write ${c.sceneCount} scenes. Each scene is one camera shot with 1 or 2 spoken lines. Each line is at most 16 words, punchy, mostly dialogue between the characters. Use the Narrator rarely.
- Total spoken words across all lines must be between ${c.minWords} and ${c.maxWords}.
- Child-friendly: no violence, nothing scary, no real brands or real people.
- Spoken text: Arabic only, no emojis, no stage directions, write numbers as words.
- image_prompt is in ENGLISH and describes only the setting, camera angle, action, emotions and props of that shot (choose luxurious, realistic settings such as: a Victorian salon with chandeliers and a grand piano, an elegant tea table with a porcelain tea set, a modern marble penthouse living room, a theatre stage with purple velvet curtains and ring lights, a grand dining hall, a palace garden, a royal kitchen, an upscale office). Do NOT describe the cats' fur or clothes: their looks are added automatically.
- characters lists the cast names visible in that shot.

Return ONLY valid JSON in exactly this shape:
{"title":"Arabic title, max 60 characters, one fitting emoji, ending with ' | BOMBO'","description":"two short Arabic sentences","tags":["8 to 12 Arabic and English keywords"],"scenes":[{"image_prompt":"...","characters":["Bombo","Lolo"],"lines":[{"speaker":"Bombo","text":"..."}]}]}`;
return [{ json: { requestBody: { contents: [{ role: 'user', parts: [{ text: prompt }] }], generationConfig: { responseMimeType: 'application/json', temperature: 1 } } } }];

const sd = $getWorkflowStaticData('global');
const c = $('Config').first().json;
const chars = JSON.parse(c.charactersJson);
const byName = {};
chars.forEach((x) => { byName[x.name.toLowerCase()] = x; });
const fail = (msg) => {
  sd.feedback = 'PREVIOUS ATTEMPT REJECTED: ' + msg + '. Fix exactly this.';
  return [{ json: { ok: false, reason: msg } }];
};
let pkg;
try {
  const parts = $input.first().json.candidates[0].content.parts;
  const t = parts.map((p) => p.text || '').join('').trim();
  pkg = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1));
} catch (e) { return fail('output was not valid JSON'); }
if (!pkg.title || !pkg.description || !Array.isArray(pkg.tags) || !Array.isArray(pkg.scenes)) return fail('missing title, description, tags or scenes');
if (pkg.scenes.length < 6 || pkg.scenes.length > 12) return fail('need 6 to 12 scenes, got ' + pkg.scenes.length);
let words = 0;
for (let i = 0; i < pkg.scenes.length; i++) {
  const s = pkg.scenes[i];
  if (!s.image_prompt || !Array.isArray(s.lines) || !s.lines.length) return fail('scene ' + (i + 1) + ' needs image_prompt and lines');
  for (const l of s.lines) {
    if (!l.text || !byName[String(l.speaker).toLowerCase()]) return fail('unknown speaker "' + l.speaker + '" in scene ' + (i + 1));
    words += String(l.text).trim().split(/\s+/).length;
  }
}
if (words < c.minWords || words > c.maxWords) return fail('total spoken words were ' + words + ', must be between ' + c.minWords + ' and ' + c.maxWords);
const tok = (s) => new Set(String(s).toLowerCase().split(/[\s,.;:!?"'()|،؟\-]+/).filter(Boolean));
const sim = (a, b) => { const A = tok(a), B = tok(b); let k = 0; A.forEach((x) => { if (B.has(x)) k++; }); return k / Math.max(1, A.size + B.size - k); };
if ((sd.titles || []).some((p) => sim(pkg.title, p) > 0.6)) return fail('title too similar to a past episode');

const base = chars.find((x) => x.look);
const looksFor = (s) => {
  let names = (s.characters || []).map((n) => String(n).toLowerCase());
  if (!names.length) names = s.lines.map((l) => String(l.speaker).toLowerCase());
   names = [...new Set(names)].filter((n) => byName[n] && byName[n].look).slice(0, 2);
  const list = names.length ? names.map((n) => byName[n]) : [base];
  return list.map((x) => x.look).join('. ');
};
const frame = (action, looks) => ('Scene: ' + String(action).slice(0, 220) + '. ' + looks + '. ' + c.stylePrompt + '. Vertical 9:16, no text, no watermark').slice(0, 1000);
const mkScene = (prompt, text, voice, zoom, tag) => ({
  comment: tag, duration: -1, 'background-color': '#111111',
  elements: [
    { type: 'image', model: c.imageModel, prompt, 'aspect-ratio': 'vertical', resize: 'cover', duration: -2, zoom },
    { type: 'voice', text, model: 'azure', voice }
  ]
});
const scenes = [];
let n = 0;
pkg.scenes.forEach((s, i) => {
  const prompt = frame(s.image_prompt, looksFor(s));
  s.lines.forEach((l) => {
    n++;
    scenes.push(mkScene(prompt, String(l.text).trim(), byName[String(l.speaker).toLowerCase()].voice, n % 2 ? 3 : 2, 'scene ' + (i + 1)));
  });
});
const outroSpeaker = byName[String(c.outroSpeaker).toLowerCase()] || base;
scenes.push(mkScene(
  frame('Bombo and Lolo smiling and waving happily at the camera in an elegant Victorian salon with chandeliers, warm cheerful mood', byName['bombo'] && byName['lolo'] ? byName['bombo'].look + '. ' + byName['lolo'].look : base.look),
  c.outroLine, outroSpeaker.voice, 3, 'outro'));

const movieElements = [{
  type: 'subtitles', language: 'ar',
  settings: { style: 'classic', 'font-family': 'Cairo', 'font-size': 70, 'word-color': '#FFD700', 'line-color': '#FFFFFF', 'outline-color': '#000000', 'outline-width': 4, position: 'bottom-center' }
}];
if (c.musicUrl && String(c.musicUrl).startsWith('http')) movieElements.push({ type: 'audio', src: c.musicUrl, volume: 0.12, loop: -1, duration: -2 });
const payload = { resolution: 'instagram-story', quality: 'high', scenes, elements: movieElements };

let title = String(pkg.title).trim().slice(0, 70);
if (!/bombo/i.test(title)) title += ' | BOMBO';
const tags = [...new Set([...pkg.tags, 'بومبو', 'BOMBO', 'قطط', 'كرتون', 'shorts'])].slice(0, 15);
const description = String(pkg.description).trim() + '\n\n' + c.descFooter;
sd.attempts = 0;
sd.feedback = '';
return [{ json: { ok: true, words, pkg: { title, description, tags }, payload } }];

const sd = $getWorkflowStaticData('global');
const start = $('Start Render').first().json;
if (!start.project) throw new Error('JSON2Video did not start the render: ' + JSON.stringify(start).slice(0, 300));
const m = $input.first().json.movie || {};
sd.polls = (sd.polls || 0) + 1;
if (m.status === 'error') throw new Error('JSON2Video render failed: ' + (m.message || 'unknown'));
if (m.status !== 'done' && sd.polls > 30) throw new Error('Render timed out after ' + sd.polls + ' checks');
if (m.status === 'done' && !m.url) throw new Error('Render finished without a URL');
return [{ json: { done: m.status === 'done', status: m.status, url: m.url || null, duration: m.duration || null } }];

const sd = $getWorkflowStaticData('global');
sd.uploadingDay = new Date().toLocaleDateString('en-CA', { timeZone: 'Africa/Cairo' });
return $input.all();

const sd = $getWorkflowStaticData('global');
const pkg = $('Quality Gate').last().json.pkg;
const yt = $('YouTube Upload').first().json;
const id = yt.id || yt.uploadId;
sd.titles = [...(sd.titles || []), pkg.title].slice(-60);
sd.polls = 0;
return [{ json: { id, title: pkg.title, url: 'https://youtube.com/shorts/' + id } }];
